package com.rodrigosambade.androidtesting; import androidx.test.ext.junit.rules.ActivityScenarioRule;import org.junit.*;import org.junit.runner.RunWith;import androidx.test.ext.junit.runners.AndroidJUnit4;import static androidx.test.espresso.Espresso.onView;import static androidx.test.espresso.action.ViewActions.click;import static androidx.test.espresso.assertion.ViewAssertions.matches;import static androidx.test.espresso.matcher.ViewMatchers.*;@RunWith(AndroidJUnit4.class) public class CounterEspressoTest{@Rule public ActivityScenarioRule<MainActivity> rule=new ActivityScenarioRule<>(MainActivity.class);@Test public void incrementsCounter(){onView(withId(R.id.increment_button)).perform(click());onView(withId(R.id.counter)).check(matches(withText("1")));}}